    ISA.behavior_or_op(instr_dec->F_Type_RRR.op, instr_dec->F_Type_RRR.op1, instr_dec->F_Type_RRR.r, instr_dec->F_Type_RRR.s, instr_dec->F_Type_RRR.t, instr_dec->F_Type_RRR.op2);
